int countVowels(String s) {
  const vowels = 'aeiouyаеёиоуыэюя';
  return s.toLowerCase().split('').where((c) => vowels.contains(c)).length;
}

List<int> oddSquares(List<int> nums) {
  return nums.where((n) => n.isOdd).map((n) => n * n).toList();
}

String capitalizeWords(String s) {
  return s.split(' ').map((w) => w.isEmpty ? w : w[0].toUpperCase() + w.substring(1)).join(' ');
}

Map<String, int> charCount(String s) {
  final m = <String, int>{};
  for (final c in s.split('')) {
    m[c] = (m[c] ?? 0) + 1;
  }
  return m;
}

String topUser(List<Map<String, dynamic>> orders) {
  final totals = <String, int>{};
  for (final o in orders) {
    totals[o['user']] = (totals[o['user']] ?? 0) + (o['amount'] as int);
  }
  return totals.entries.reduce((a, b) => a.value >= b.value ? a : b).key;
}

bool isPrime(int n) {
  if (n < 2) return false;
  for (var i = 2; i * i <= n; i++) {
    if (n % i == 0) return false;
  }
  return true;
}

List<int> fibonacci(int n) {
  final out = <int>[];
  var a = 0, b = 1;
  for (var i = 0; i < n; i++) {
    out.add(a);
    final next = a + b;
    a = b;
    b = next;
  }
  return out;
}

int grade(int score) {
  if (score >= 90) return 5;
  if (score >= 75) return 4;
  if (score >= 60) return 3;
  return 2;
}

String compress(String s) {
  final b = StringBuffer();
  var i = 0;
  while (i < s.length) {
    var j = i;
    while (j < s.length && s[j] == s[i]) j++;
    b.write('${s[i]}${j - i}');
    i = j;
  }
  return b.toString();
}

