class BankAccount {
  int _balance;
  BankAccount(this._balance);

  int get balance => _balance;

  void deposit(int amount) => _balance += amount;

  void withdraw(int amount) {
    if (amount <= _balance) _balance -= amount;
  }
}

class Rectangle {
  final int width, height;
  Rectangle(this.width, this.height);

  int get area => width * height;
  bool get isSquare => width == height;
}

class Square extends Rectangle {
  Square(int side) : super(side, side);
}

int digitalRoot(int n) {
  while (n >= 10) {
    n = n.toString().split('').map(int.parse).reduce((a, b) => a + b);
  }
  return n;
}

bool isBalanced(String s) {
  const pairs = {')': '(', ']': '[', '}': '{'};
  final stack = <String>[];
  for (final c in s.split('')) {
    if ('([{'.contains(c)) {
      stack.add(c);
    } else if (pairs.containsKey(c)) {
      if (stack.isEmpty || stack.removeLast() != pairs[c]) return false;
    }
  }
  return stack.isEmpty;
}

String toClock(int seconds) {
  String two(int n) => n.toString().padLeft(2, '0');
  return '${two(seconds ~/ 3600)}:${two(seconds % 3600 ~/ 60)}:${two(seconds % 60)}';
}

int secondLargest(List<int> nums) {
  final sorted = nums.toSet().toList()..sort();
  return sorted[sorted.length - 2];
}
